// The publish-pages code-work entry point — the script the executor runs as
// `node worker.mjs` (cwd = this task dir, bounded by code_work_timeout).
//
// Three steps, each of which has to succeed before the next is worth starting:
//
//   1. BUILD. `build-site.mjs` assembles the site into a scratch directory. A
//      declaration the build refuses (no `mode`, a contradicting roster) fails here,
//      in the executor's log. A mount that does not yet carry the page is the build's
//      own "nothing to publish", and the run ends there as an empty outcome.
//   2. PUSH. The built tree becomes one root commit force-pushed to the Pages branch.
//      No history: the branch is a regenerate-wholesale surface, and a site that has
//      been published before is just as published from one commit as from a thousand.
//      The push uses the Action's own token — `contents: write` is the executor's
//      already — and a push to the Pages branch is what starts Pages' own build.
//   3. WATCH. A push answers before anything is live, so the run reads the site back:
//      the build carries a stamp of its own, and the run is done when the public URL
//      serves it. A site that never does within the watch is the one non-code
//      failure a branch deploy has — Pages not enabled on this branch, a repository
//      setting no Action can flip — and parks for the person who can flip it.
//
// Runnable by hand from anywhere, given a token that may push the Pages branch:
//   GITHUB_TOKEN=… CLAUDINITE_REPO=owner/name CLAUDINITE_REPO_ROOT=/path/to/member node worker.mjs

import { execFileSync, spawn } from 'node:child_process';
import { access, mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { deploymentConfig } from '../../deployment-config.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));

// The site assembler, in the pack above this task. One canonical spelling of the
// path; nothing else here names the file.
export const BUILD_SCRIPT = resolve(HERE, '../../build-site.mjs');

// The branch Pages publishes from — the name GitHub's own settings page offers first,
// and the one every branch-deploy tool defaults to. The Pages source setting names it
// once, at adoption, so it is not configurable: a member that changed it would move
// its site out from under the setting.
export const PAGES_BRANCH = 'gh-pages';

// The file the watch reads back. At the site root, beside `.nojekyll`, where nothing
// in the page's own tree can shadow it.
export const STAMP_FILE = 'deployed.json';

// A park the operator can act on, in the executor's own vocabulary: the last marker
// printed decides the lane. `action` means something outside the code must change
// before this can run; `decision` means the run stopped and the next step is a choice.
export class NeedsHuman extends Error {
  constructor(kind, message) { super(message); this.kind = kind; }
}

const item = process.env.CLAUDINITE_ITEM || '';
const defaultLog = (s) => console.log(`publish-pages${item ? ` [#${item}]` : ''}: ${s}`);

const exists = async (p) => { try { await access(p); return true; } catch { return false; } };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export const remoteUrl = (repo, token) => `https://x-access-token:${token}@github.com/${repo}.git`;

// WHERE THE SITE IS SERVED. Stated by the declaration when it names the page's own
// URL (`redirectUri` is the dashboard page, one directory below the site root), and
// otherwise GitHub's rule for a project site — `https://<owner>.github.io/<name>/`,
// or the owner's root when the repo IS the owner's Pages site. A custom domain has
// no other source than the declaration.
export function siteRoot(cfg, repo) {
  if (cfg?.redirectUri) {
    try {
      const u = new URL(cfg.redirectUri);
      const i = u.pathname.indexOf('/packs/claudinite-dashboard');
      const path = i >= 0 ? u.pathname.slice(0, i + 1) : u.pathname.replace(/[^/]*$/, '');
      return `${u.origin}${path}`;
    } catch { /* fall through to the rule */ }
  }
  const [owner, name] = String(repo).split('/');
  const host = `https://${owner.toLowerCase()}.github.io/`;
  return name.toLowerCase() === `${owner.toLowerCase()}.github.io` ? host : `${host}${name}/`;
}

// --- 1. build --------------------------------------------------------------------

// Run the assembler exactly as an operator would, into `out`. Resolves `{ built,
// output }`: `built` false is the script's own clean "no dashboard in the mount"
// exit, not a failure.
export async function buildInto(out, { repoRoot, log = defaultLog, run = spawnBuild }) {
  const { code, output } = await run([BUILD_SCRIPT, '--root', repoRoot, '--out', out]);
  for (const line of output.trim().split('\n').filter(Boolean)) log(`build: ${line}`);
  if (code !== 0) throw new Error(`build-site.mjs exited ${code}`);
  return { built: await exists(join(out, 'index.html')), output };
}

function spawnBuild(args) {
  return new Promise((resolveRun, reject) => {
    const child = spawn(process.execPath, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let output = '';
    child.stdout.on('data', (d) => { output += d; });
    child.stderr.on('data', (d) => { output += d; });
    child.on('error', reject);
    child.on('close', (code) => resolveRun({ code, output }));
  });
}

// --- 2. push ---------------------------------------------------------------------

const git = (cwd, args, opts = {}) => execFileSync('git', ['-C', cwd, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });

// The built tree as one root commit on the Pages branch. Force, always: the branch
// holds the last build and nothing else, so there is no history to keep and no
// reconcile to do — and a re-run of the same sources is a re-push, not a conflict.
export function pushSite(out, { remote, branch = PAGES_BRANCH, message }) {
  git(out, ['init', '--quiet', '--initial-branch', branch]);
  git(out, ['add', '--all']);
  const author = ['-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com'];
  git(out, [...author, 'commit', '--quiet', '--message', message]);
  const sha = git(out, ['rev-parse', 'HEAD']).trim();
  try {
    git(out, ['push', '--quiet', '--force', remote, `HEAD:refs/heads/${branch}`]);
  } catch (e) {
    // The token is in the remote URL; keep it out of the trace.
    throw new Error(`push to ${branch} failed: ${String(e.stderr ?? e.message).replace(/x-access-token:[^@]*@/g, 'x-access-token:***@')}`);
  }
  return sha;
}

// --- 3. watch --------------------------------------------------------------------

// True once the site serves this build's stamp; false if it never did before the
// deadline. Each read carries a fresh query string so the CDN's edge cache cannot
// answer for the previous build.
export async function watchSite(url, stamp, { deadline, wait = 15000, fetchImpl = fetch, log = defaultLog } = {}) {
  let last = null;
  for (;;) {
    let seen = null;
    try {
      const res = await fetchImpl(`${url}?${Date.now()}`, { headers: { 'cache-control': 'no-cache' } });
      if (res.status === 200) seen = (await res.json())?.stamp ?? null;
      else seen = `HTTP ${res.status}`;
    } catch (e) {
      seen = `unreachable (${e.message})`;
    }
    if (seen === stamp) return true;
    if (seen !== last) { log(`site serves ${seen ?? 'no stamp'} — waiting for ${stamp}`); last = seen; }
    if (Date.now() >= deadline) return false;
    await sleep(wait);
  }
}

export async function main({
  repoRoot = process.env.CLAUDINITE_REPO_ROOT,
  repo = process.env.CLAUDINITE_REPO,
  token = process.env.GITHUB_TOKEN,
  remote = null,
  log = defaultLog,
  fetchImpl = fetch,
  // Well inside `code_work_timeout`, so a site still turning over when this gives up
  // is reported rather than killed mid-sentence.
  watchMs = 12 * 60 * 1000,
  watchWait = 15000,
} = {}) {
  if (!repoRoot || !repo) throw new Error('CLAUDINITE_REPO_ROOT and CLAUDINITE_REPO are required');
  if (!remote && !token) throw new Error('GITHUB_TOKEN is not set — the executor always provides it');

  const out = await mkdtemp(join(tmpdir(), 'claudinite-dashboard-'));
  try {
    const { built } = await buildInto(out, { repoRoot, log });
    if (!built) {
      log('nothing to publish — the mount does not yet carry the dashboard, so nothing was pushed');
      return { published: false, reason: 'no-site' };
    }

    // What the watch looks for: the sources' sha, made unique per run so a re-publish
    // of unchanged sources is still told apart from the build already live.
    const source = git(repoRoot, ['rev-parse', 'HEAD']).trim();
    const stamp = `${source}:${Date.now()}`;
    await writeFile(join(out, STAMP_FILE), `${JSON.stringify({ stamp, source, builtAt: new Date().toISOString() }, null, 2)}\n`);

    const sha = pushSite(out, {
      remote: remote ?? remoteUrl(repo, token),
      message: `Claudinite dashboard built from ${source.slice(0, 12)}${item ? ` (#${item})` : ''}\n\nClaudinite-Task: claudinite-dashboard/publish-pages`,
    });
    log(`pushed ${sha.slice(0, 12)} to ${PAGES_BRANCH}`);

    const { cfg } = await deploymentConfig(repoRoot);
    const url = `${siteRoot(cfg, repo)}${STAMP_FILE}`;
    log(`watching ${url}`);
    const live = await watchSite(url, stamp, { deadline: Date.now() + watchMs, wait: watchWait, fetchImpl, log });
    if (!live) {
      throw new NeedsHuman('action', `${PAGES_BRANCH} carries the new build but ${url} did not serve it within ${Math.round(watchMs / 60000)} minutes — `
        + `enable GitHub Pages on ${repo} with source "Deploy from a branch", branch ${PAGES_BRANCH}, folder / (root), under /settings/pages, then re-queue`);
    }
    log(`published — ${siteRoot(cfg, repo)}`);
    return { published: true, sha, url: siteRoot(cfg, repo) };
  } finally {
    await rm(out, { recursive: true, force: true });
  }
}

const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMain) {
  main().catch((e) => {
    console.error(e instanceof NeedsHuman
      ? `claudinite-needs-human: ${e.kind} — ${e.message}`
      : `publish-pages failed: ${e.stack ?? e.message}`);
    process.exit(1);
  });
}
EOF
cat > $P/tasks/publish-pages/README.md <<'EOF'
# publish-pages

Republishes the dashboard site to GitHub Pages when the page's sources have moved,
and does not report success until the live site serves the build it pushed.

The task runs no agent and needs no workflow: `worker.mjs` builds the site with
[`build-site.mjs`](../../build-site.mjs), force-pushes the result as one commit to the
`gh-pages` branch, and reads the site back until it serves that build's stamp.

## Why a branch, not the Pages actions

`actions/deploy-pages` and its siblings are `uses:` steps, which only workflow YAML
can invoke — and `.github/workflows/` is the one directory the nightly update cannot
converge, so a deploy built on them is frozen at adoption. A site published **from a
branch** needs none of that: a push to the branch is what starts Pages' own build,
the Action's token may make that push, and the whole deploy is code that moves with
the pack.

## What it needs

| Where | Name | What it is |
|---|---|---|
| Repository setting | Pages, source *Deploy from a branch*, branch `gh-pages`, folder `/ (root)` | the one step no Action can take. The branch exists after the first run; until the setting names it the run parks at `needs-human-action` saying so |
| Repo **variable** | `CLAUDINITE_DASHBOARD_CLIENT_ID`, `CLAUDINITE_DASHBOARD_EXCHANGE_URL` | *optional*; the sign-in pair, read by the build |
| Declaration `config` | `redirectUri` | *optional*; where the site is served, for a custom domain. Otherwise the watch reads `https://<owner>.github.io/<repo>/` |

No secret: the push uses the Action's own token.

## When it runs

Daily, after the `claudinite-lifecycle/update` task, and only when the mount or the
member's declaration moved in the window. A change to either repository variable is
not a signal the queue sees — force a republish with `create-work-item --wake` on the
task's standing item.

## What a run does

1. Builds the site into a scratch directory. A build that refuses (no `mode`) fails
   here; a mount that does not carry the page yet ends the run with nothing to publish.
2. Writes `deployed.json` at the site root — the sources' sha and a per-run stamp —
   and force-pushes the tree as a single root commit to `gh-pages`. No history is kept:
   the branch holds the last build and nothing else.
3. Reads `deployed.json` back from the live site, cache-busted, until it carries the
   stamp. A site that never does parks for the person who can point Pages at the branch.
