// claudinite-dashboard task: publish-pages — republish the dashboard site when the
// page's sources have moved, and prove the deploy landed.
//
// WHY A TASK AND A WORKFLOW. The Pages deploy is built on marketplace actions
// (`configure-pages`, `upload-pages-artifact`, `deploy-pages`), which only workflow
// YAML can invoke — code-work is a step's subprocess and cannot resolve a `uses:`,
// and the artifact those actions upload goes through a runtime credential only an
// action step is handed. So the seeded workflow keeps exactly those steps and nothing
// else: no build, no inputs, nothing that could ever need to change in the one file
// the nightly update cannot converge. This task owns the rest — the decision to run,
// the build, the branch that carries the built tree to the runner, the trigger, and
// the follow-through.
//
// `daily`, after the converge: the push that moves the page's sources most often is
// the nightly update, which lands over the Actions token. Yielding to it puts this
// run in the same cycle, on the mount it just delivered.
//
// `agent_model: 'none'` — pure code. Build, push, dispatch, follow, report.

export default {
  id: 'publish-pages',
  frequency: 'daily',
  // The page is a function of the mount and of the member's own declaration, and of
  // nothing else in the tree. A day on which neither moved has nothing to republish.
  // (The sign-in pair are repository variables, which no signal covers: a changed
  // client id or exchange URL is a forced run — `create-work-item --wake`.)
  preconditions: ['mount-moved || commits-under:.claudinite-settings.json || commits-under:.claudinite-checks.json'],
  schedule_after: ['claudinite-lifecycle/update'],
  agent_model: 'none',
  // It opens no PR and touches no source branch: its one write is the `gh-pages`
  // branch, a regenerate-wholesale surface that holds nothing but the last build.
  expected_outcome: 'none',
  code_work: 'node worker.mjs',
  // A local build (seconds), one push, one dispatch, then following one Pages run:
  // checkout and deploy together take about a minute, and the follow allows for a
  // queued runner.
  code_work_timeout: 600,
};
EOF
