=== ci.yml unit tests step:
        with:
          node-version: 20
      - name: Unit tests
        # THE test roots — a closed set of FOLDERS, each swept to any depth. Depth is
        # deliberately not enumerated: the previous form spelled out one glob per level of
        # nesting, so a test at an unlisted depth was silently never run — which is exactly
        # how vendoring/'s two files sat outside CI. `**` removes depth from the question;
        # what remains is the root list, and engine-tests/ci-test-roots.test.mjs fails the
        # moment a tracked test lands outside it. Adding a root is a deliberate CI edit;
        # adding a test is not.
        #   engine-tests/            engine/ (migrations included) + the other top-level canon code;
        #                            mirrors engine/'s inner structure, and stays canon-side
        #                            because engine/ ships to consumers exactly as-is (#385)
        #   packs/                   every canon pack's tests, each inside the pack it covers
        #   vendoring/               co-located with the vendor computer/writer they cover,
        #                            the fixture-consumer rehearsal included
        #   dev/tools/               maintainer-side tooling nothing at session time runs
        #   .claudinite/local/packs/ this repo's own local packs — tests live inside the tree
        # nullglob: a root with no tests drops out instead of reaching node as a literal pattern.
        run: |
          shopt -s globstar nullglob
          tests=(engine-tests/**/*.test.mjs packs/**/*.test.mjs vendoring/**/*.test.mjs dev/tools/**/*.test.mjs .claudinite/local/packs/**/*.test.mjs)
          # Deliberately oversubscribed. node --test defaults to one worker per core
          # minus one, which fits a CPU-bound suite; this one spends most of its wall
          # clock waiting — on git plumbing, spawned workers and converge fixtures — so
          # the cores idle at that default (measured on this tree: 106s wall against
          # 187s of user+sys on 4 cores). Doubling the workers: 106s -> 70s, with 16
          # buying only another 2s.
          #
          # TAP goes to a FILE, not the log. 2,448 tests emit ~13,000 lines at 5.3
          # lines each, and a failing run's one `not ok` sits wherever its file
          # finished — while GitHub's job-log API serves only a TAIL and the signed
          # blob URL that would serve the whole thing is proxy-blocked. So a red run
          # said `# fail 1` and nothing more, and five green local re-runs could not
          # name the test (#1170). Printing the failing blocks puts the identity in
          # the tail, where it can actually be read.
          status=0
          node --test --test-concurrency=$(( $(nproc) * 2 )) "${tests[@]}" > "$RUNNER_TEMP/tests.tap" || status=$?
          if [ "$status" -ne 0 ]; then
            echo '::group::failing tests'
            grep -n -A 25 '^not ok' "$RUNNER_TEMP/tests.tap" || echo 'no `not ok` line — the runner died before reporting one'
            echo '::endgroup::'
          fi
          tail -n 12 "$RUNNER_TEMP/tests.tap"
          exit "$status"
      - name: Conformance sweep (world scope)
=== deployment-config.test.mjs around stub read:
  assert.deepEqual(legacy, []);
});

// The hole a variable opens that a config key does not: the deploy workflow skips the
// build when a cache key over the SOURCE FILES is unchanged, and no file hash covers a
// repository variable. Without the pair in the key, changing either would hit the cache
// and leave the site serving the previous client id with nothing to show for it.
test('the seeded workflow passes both variables and folds them into its cache key', () => {
  const yml = readFileSync(join(PACK_DIR, 'stubs/workflows/claudinite-dashboard-pages.yml'), 'utf8');
  for (const name of Object.values(SIGN_IN_VARS)) {
    assert.match(yml, new RegExp(`${name}: \\$\\{\\{ vars\\.${name} \\}\\}`),
      `${name} must reach the build`);
  }
  const sources = /- name: What the page would be built from[\s\S]*?(?=\n      - )/.exec(yml)?.[0] ?? '';
  // The KEY LINE, not the step around it: the variables also appear in this step's own
  // `env:`, so asserting over the whole block passes just as happily with the digest
  // dropped from the key — which is the entire bug this test exists for.
  const keyLine = sources.split('\n').find((l) => l.includes('key=dashboard-deployed-'));
  assert.ok(keyLine, 'the step must still compute a cache key');
  const digest = /signin=\$\(([^)]*\)[^)]*)\)/.exec(sources)?.[0] ?? '';
  assert.match(digest, /sha256sum/, 'the variables must be hashed into something');
  for (const name of Object.values(SIGN_IN_VARS)) {
    assert.ok(digest.includes(name), `${name} must be part of that digest`);
  }
  assert.match(keyLine, /\$signin/, 'and the digest must actually be in the cache key');
});
=== pack.test.mjs 40-56 + 370-386:
  // that file's presence, so its absence is the declaration.
  assert.equal(existsSync(join(PACK_DIR, 'RULES.md')), false);
  assert.equal(pack.prose, undefined);
  // The one check guards what OTHER packs contribute to this page — a descriptor the
  // reader rejects fails silently, in a viewer's browser, where its author never
  // looks. It is a world rule: it audits what has landed, whatever this session
  // touched.
  // It is the module in the pack's own worldRules/ — the directory is the
  // declaration, so the directory is what this asserts.
  assert.deepEqual(readdirSync(join(PACK_DIR, 'worldRules')).sort(),
    ['descriptor-usable.mjs']);
  assert.equal(existsSync(join(PACK_DIR, 'workRules')), false);
});

// The whole point of the remodel: adoption is what wires the deploy, because
// `.github/workflows/` cannot be written by the nightly and so can only be seeded.
test('adoption seeds the Pages workflow, and its template exists', async () => {
  assert.match(signin.step, /README/i, 'and points at where the mechanics are');
  // The trap this guards: an entry that reads as mandatory when the deployment may
  // legitimately have nothing to do.
  assert.match(signin.step, /nothing to do|leave it/i, 'the do-nothing answer is stated as an answer');
  assert.match(signin.breaks, /60 requests\/hour|anonymous/i, 'what being undone actually costs');
  assert.match(signin.done, /5000|token box/, 'and something that can close it either way');
});

// The point of the field over a README line: a README is read after the deploy has
// already failed. This asserts the install flow actually surfaces it.
test('the install flow reports the handover so adoption cannot miss it', async (t) => {
  const dir = await mkdtemp(join(tmpdir(), 'cd-install-'));
  t.after(() => rm(dir, { recursive: true, force: true }));
  await writeFile(join(dir, '.claudinite-settings.json'), JSON.stringify({ packs: [] }, null, 2));

  const { stdout } = await runReporting('node',
    [join(ROOT, 'packs/claudinite-lifecycle/updates/install.mjs'), '--target', dir, 'claudinite-dashboard'],
    { cwd: ROOT });

  assert.match(stdout, /only a human can do/, 'the handover is printed');
  assert.match(stdout, /\[ \] \(claudinite-dashboard\) Enable GitHub Pages/);
  assert.match(stdout, /\[ \] \(claudinite-dashboard\) Decide how this dashboard authenticates/);
  assert.match(stdout, /while off:/);
  assert.match(stdout, /done when:/);
  // And the thing it is a handover FOR actually landed.
  assert.match(stdout, /seeded \.github\/workflows\/claudinite-dashboard-pages\.yml/);
});
