# Deploy the Claudinite task dashboard to GitHub Pages.
#
# SEEDED ONCE, AT ADOPTION — `.github/workflows/` is the one directory the nightly
# update cannot push to — so this holds only what needs a workflow job: the Pages
# actions, which `uses:` alone can invoke. Nothing here decides, builds or configures.
# The `claudinite-dashboard/publish-pages` task does all of that, pushes the built tree
# to `gh-pages`, and fires this by `workflow_dispatch`. Dispatching by hand redeploys
# the last build; a rebuild is the task's (`create-work-item --wake`).

name: Claudinite dashboard

on:
  workflow_dispatch:

permissions:
  contents: read
  pages: write
  id-token: write

concurrency:
  group: claudinite-dashboard-pages
